BEGIN;
UPDATE public.restaurant_settings SET name='O‘ktam bobo choyxonasi', description=replace(description,'O‘ktam ota','O‘ktam bobo');
UPDATE public.menu_items SET description='{"uz": "Qo‘y go‘shtidan donalik shashlik. Qo‘y go‘shtini yoqtiradiganlar uchun.", "ru": "Поштучный шашлык из баранины — для любителей этого мяса.", "en": "Lamb shashlik, priced by the skewer."}'::jsonb WHERE id='qoy-koska';
UPDATE public.menu_items SET description='{"uz": "Mol go‘shtidan donalik shashlik. Dasturxon uchun go‘shtli tanlov.", "ru": "Поштучный шашлык из говядины для вашего стола.", "en": "Beef shashlik, priced by the skewer."}'::jsonb WHERE id='mol-koska';
UPDATE public.menu_items SET description='{"uz": "Keskis — donalik shashliklarimizdan biri. Boshqa turlar bilan birga tanlab ko‘ring.", "ru": "«Кескис» — один из наших поштучных шашлыков. Можно выбрать вместе с другими видами.", "en": "Keskis is one of our individual shashlik options. Try it alongside another selection."}'::jsonb WHERE id='keskis-shashlik';
UPDATE public.menu_items SET description='{"uz": "Koska rulet — shashlik menyusidagi rulet varianti. Narx 1 dona uchun.", "ru": "«Коска-рулет» — вариант рулета в нашем меню шашлыков. Цена за штуку.", "en": "Koska roll is a roll-style option from our shashlik menu. Priced per piece."}'::jsonb WHERE id='koska-rulet';
UPDATE public.menu_items SET description='{"uz": "Qo‘y biqinidan tayyorlanadigan shashlik. Narx 1 dona uchun.", "ru": "Шашлык из бараньего бока. Цена за штуку.", "en": "Shashlik made from lamb flank. Priced per piece."}'::jsonb WHERE id='qoy-biqin';
UPDATE public.menu_items SET description='{"uz": "Bomba — donalik shashliklar menyusidagi alohida tanlov. Narx 1 dona uchun.", "ru": "«Бомба» — отдельный вариант в меню поштучных шашлыков. Цена за штуку.", "en": "Bomba is a distinct option in our individual shashlik selection. Priced per piece."}'::jsonb WHERE id='bomba';
UPDATE public.menu_items SET description='{"uz": "Rulet shashlik — rulet ko‘rinishidagi donalik tanlov.", "ru": "Шашлык-рулет — поштучный вариант в форме рулета.", "en": "Roll shashlik, served as an individual piece."}'::jsonb WHERE id='rulet';
UPDATE public.menu_items SET description='{"uz": "Qo‘y jigaridan tayyorlangan shashlik. Jigar taomlarini yoqtiradiganlar uchun.", "ru": "Шашлык из бараньей печени — для любителей блюд из печени.", "en": "Lamb liver shashlik for those who enjoy liver dishes."}'::jsonb WHERE id='qoy-jigar';
UPDATE public.menu_items SET description='{"uz": "Tovuq go‘shtidan tayyorlangan donalik shashlik.", "ru": "Поштучный шашлык из куриного мяса.", "en": "Chicken shashlik, priced by the skewer."}'::jsonb WHERE id='tovuq';
UPDATE public.menu_items SET description='{"uz": "Qiymadan tayyorlangan shashlik. Donalik va kiloli variantlari menyuda alohida ko‘rsatilgan.", "ru": "Шашлык из фарша. Поштучный вариант и вариант на килограмм указаны отдельно.", "en": "Minced meat shashlik. Individual and kilogram options are listed separately."}'::jsonb WHERE id='qiyma';
UPDATE public.menu_items SET description='{"uz": "Issiq sho‘rva — bir kosa uchun 40 000 so‘m.", "ru": "Горячая шурпа — 40 000 сум за одну косу (пиалу).", "en": "Hot shurpa soup — 40,000 UZS per bowl."}'::jsonb, price=40000, price_unit='portion', portion='{"uz":"1 kosa","ru":"1 коса","en":"1 bowl"}'::jsonb WHERE id='shorva';
UPDATE public.announcements SET title=replace(title,'O‘ktam ota','O‘ktam bobo'), content=replace(content,'O‘ktam ota','O‘ktam bobo');
UPDATE public.restaurant_settings SET description_i18n=replace(description_i18n::text,'O‘ktam ota','O‘ktam bobo')::jsonb WHERE description_i18n IS NOT NULL;
UPDATE public.announcements SET title_i18n=replace(title_i18n::text,'O‘ktam ota','O‘ktam bobo')::jsonb WHERE title_i18n IS NOT NULL;
UPDATE public.announcements SET content_i18n=replace(content_i18n::text,'O‘ktam ota','O‘ktam bobo')::jsonb WHERE content_i18n IS NOT NULL;
COMMIT;
